    pub fn bisect_left(&self, key: &K) -> usize {
        self.entries.bisect_left_by(|entry| entry.key.cmp(key))
    }

    /// Rank of the first key greater than `key`.
    pub fn bisect_right(&self, key: &K) -> usize {
        self.entries.bisect_right_by(|entry| entry.key.cmp(key))
    }
