impl<K: Ord, V> FromIterator<(K, V)> for SortedDict<K, V> {
    fn from_iter<I: IntoIterator<Item = (K, V)>>(iter: I) -> Self {
        let mut dict = SortedDict::new();
        for (key, value) in iter {
            dict.insert(key, value);
        }
        dict
    }
}

